"""PL-02 step 2: daily log returns from aligned closes."""

from __future__ import annotations

from mdata import Prices
from risk.types import Returns


def log_returns(prices: Prices) -> Returns:
    """Spine: simple returns r_t = close_t / close_t-1 - 1, dated t.

    ValueError with fewer than two dates.
    """
    if len(prices.dates) < 2:
        raise ValueError(f"log_returns needs at least two dates, got {len(prices.dates)}")
    values = {
        ticker: tuple(
            today / yesterday - 1.0
            for yesterday, today in zip(closes[:-1], closes[1:], strict=True)
        )
        for ticker, closes in ((t, prices.closes[t]) for t in prices.tickers)
    }
    return Returns(
        base_date=prices.dates[0],
        dates=prices.dates[1:],
        tickers=prices.tickers,
        values=values,
    )

